/* Headless additive engine prototype: the real voice graph with the additive
 * oscillator and the per-voice envelope morph. The engine C is generated by
 * plugin/tools/additive_prototype.py in the build tree; the product engine is
 * untouched. */
#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <fstream>
#include <string>
#include <vector>

#include "Engine.hpp"
#include "Params.h"

extern "C" int32_t p1_additive_morph_start;
extern "C" int32_t p1_additive_morph_step;
extern "C" int32_t p1_additive_morph_now;

namespace {

constexpr int kRate = 44100;
constexpr int kVoices = 20;

double secondsSince(std::chrono::steady_clock::time_point start)
{
    return std::chrono::duration<double>(std::chrono::steady_clock::now() - start)
        .count();
}

bool setEngineParam(p1::Engine& engine, const char* id, int32_t value)
{
    for (const auto& spec : kP1ParamSpecs) {
        if (std::strcmp(spec.id, id) == 0) {
            engine.setParam(static_cast<uint32_t>(spec.engineId), value);
            return true;
        }
    }
    return false;
}

void writeWav(const std::string& path, const std::vector<int32_t>& samples)
{
    std::ofstream file(path, std::ios::binary);
    if (!file)
        return;
    const auto frames = static_cast<uint32_t>(samples.size() / 2u);
    const auto dataBytes = frames * 4u;
    auto write32 = [&file](uint32_t value) {
        const char bytes[4] = {static_cast<char>(value & 0xFF),
                               static_cast<char>((value >> 8) & 0xFF),
                               static_cast<char>((value >> 16) & 0xFF),
                               static_cast<char>((value >> 24) & 0xFF)};
        file.write(bytes, 4);
    };
    auto write16 = [&file](int16_t value) {
        const auto bits = static_cast<uint16_t>(value);
        const char bytes[2] = {static_cast<char>(bits & 0xFF),
                               static_cast<char>((bits >> 8) & 0xFF)};
        file.write(bytes, 2);
    };
    file.write("RIFF", 4);
    write32(36u + dataBytes);
    file.write("WAVEfmt ", 8);
    write32(16);
    write16(1);
    write16(2);
    write32(kRate);
    write32(kRate * 4);
    write16(4);
    write16(16);
    file.write("data", 4);
    write32(dataBytes);
    for (uint32_t i = 0; i < frames; ++i) {
        const auto left = static_cast<int16_t>(
            std::max(-32768, std::min(32767, samples[i * 2u])));
        const auto right = static_cast<int16_t>(
            std::max(-32768, std::min(32767, samples[i * 2u + 1u])));
        write16(left);
        write16(right);
    }
}

} // namespace

int main(int argc, char** argv)
{
    const std::string wavPath = argc > 1 ? argv[1] : "additive-engine.wav";
    std::printf("additive engine prototype\n");

    {
        p1::Engine engine;
        engine.reset();
        p1_additive_morph_start = 16384;
        p1_additive_morph_step = 0;
        p1_additive_morph_now = 16384;
        for (int i = 0; i < kVoices; ++i)
            engine.noteOn(static_cast<uint32_t>(48 + i * 2), 100, 0);
        std::vector<int32_t> output(static_cast<std::size_t>(kRate) * 2u);
        engine.render(output.data(), kRate);

        constexpr int kSeconds = 20;
        double best = 1e9;
        for (int run = 0; run < 3; ++run) {
            output.assign(static_cast<std::size_t>(kRate) * 2u * kSeconds, 0);
            const auto start = std::chrono::steady_clock::now();
            engine.render(output.data(),
                          static_cast<uint32_t>(kRate * kSeconds));
            best = std::min(best, secondsSince(start));
        }
        std::printf("20 voices, real graph, additive oscillator: 20 s render "
                    "%.1f ms, 60 s: %.1f ms, %.2f%% of realtime\n",
                    best * 1000.0, best * 3000.0, best / 20.0 * 100.0);
    }

    {
        p1::Engine engine;
        engine.reset();
        p1_additive_morph_start = 0;
        p1_additive_morph_step = 0;
        p1_additive_morph_now = 0;
        setEngineParam(engine, "algorithm.p0", 7);
        setEngineParam(engine, "level.p1", 0);
        setEngineParam(engine, "op1_level.p0", 99);
        setEngineParam(engine, "op1_feedback.p0", 0);
        setEngineParam(engine, "op1_fb_depth.p0", 0);
        for (const char* id : {"op2_level.p0", "op3_level.p0", "op4_level.p0"})
            setEngineParam(engine, id, 0);
        for (const char* id : {"op2_mute.p0", "op3_mute.p0", "op4_mute.p0"})
            setEngineParam(engine, id, 1);
        const int notes[4] = {60, 64, 67, 71};
        for (int note : notes)
            engine.noteOn(static_cast<uint32_t>(note), 100, 0);
        const int frames = kRate * 4;
        std::vector<int32_t> output(static_cast<std::size_t>(frames) * 2u, 0);
        for (int position = 0; position < frames; position += 32) {
            const int length = std::min(32, frames - position);
            const double t = static_cast<double>(position) / kRate;
            const int target = static_cast<int>(
                std::min(1.0, t / 4.0) * 32767.0);
            const int start = p1_additive_morph_now;
            p1_additive_morph_start = start;
            p1_additive_morph_step = (target - start) / length;
            engine.render(output.data() + position * 2, length);
        }
        writeWav(wavPath, output);
        std::printf("audition: %s (four-note chord, single clean carrier, 4 s "
                    "time ramp, engine voice path)\n",
                    wavPath.c_str());
    }
    return 0;
}
